"use client";

import Link from "next/link";
import { useEffect, useState } from "react";
import { Activity, BarChart3, BookOpenText, CalendarClock, Check, CheckCircle2, ChevronLeft, CircleDollarSign, ClipboardList, CreditCard, ExternalLink, Gift, Globe2, HandCoins, ImageUp, KeyRound, Link2, LogIn, LogOut, Mail, MessageSquare, Package, Plus, Save, Send, Settings2, Trash2, UserPlus, UserRound, UsersRound } from "lucide-react";
import { CartesianGrid, Legend, Line, LineChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import type { CoachClientDetail, CoachServiceOfferSummary, CoachWorkspaceResponse } from "@levelup/contracts";
import { coachApi, partnerPortalApi } from "@/lib/api";
import styles from "./coach.module.css";

type Tab = "overview"|"clients"|"scheduling"|"services"|"plans"|"site"|"telegram"|"rewards"|"profile";
type ClientSection = "state"|"insights"|"feedback"|"assignments";
const tabs = [
  ["overview","Обзор",BarChart3],["clients","Клиенты",UsersRound],["scheduling","Расписание",CalendarClock],["services","Услуги",HandCoins],["plans","Пакет",Package],
  ["site","Сайт",Globe2],["telegram","Telegram",MessageSquare],["rewards","Награды",Gift],["profile","Профиль",Settings2]
] as const;
const makeKey=()=>typeof crypto!=="undefined"&&crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random()}`;

export default function CoachWorkspacePage(){
  const [workspace,setWorkspace]=useState<CoachWorkspaceResponse|null>(null);
  const [tab,setTab]=useState<Tab>("overview");const [loading,setLoading]=useState(true);const [loginRequired,setLoginRequired]=useState(false);const [error,setError]=useState("");const [notice,setNotice]=useState("");const [logoutBusy,setLogoutBusy]=useState(false);
  const [checkoutPolls,setCheckoutPolls]=useState(0);
  const [selected,setSelected]=useState<CoachClientDetail|null>(null);
  const load=()=>{setLoading(true);setError("");coachApi.workspace().then((data)=>{setWorkspace(data);setLoginRequired(false);const queryReferral=new URLSearchParams(window.location.search).get("ref")?.trim();if(queryReferral)window.localStorage.setItem("orken_referral_code",queryReferral);const referral=queryReferral||window.localStorage.getItem("orken_referral_code");if(referral)void coachApi.captureAttribution(referral).catch(()=>undefined)}).catch((reason)=>{if(String(reason?.message||reason).toLowerCase().includes("login")){setLoginRequired(true)}else setError(reason instanceof Error?reason.message:"Не удалось загрузить кабинет")}).finally(()=>setLoading(false))};
  useEffect(load,[]);
  useEffect(()=>{if(!workspace)return;const status=new URLSearchParams(window.location.search).get("subscription");if(status==="cancelled"){setNotice("Оплата отменена. Пакет не подключён.");return}if(status!=="active")return;if(workspace.subscription){setNotice("Пакет подключён. Теперь можно приглашать клиентов за счёт пакета.");window.history.replaceState({},"","/coach");return}if(checkoutPolls>=4){setNotice("Платёж принят. Активация пакета ещё обрабатывается; обновите страницу через минуту.");return}setNotice("Платёж принят. Подтверждаем активацию пакета...");const timer=window.setTimeout(()=>{setCheckoutPolls(value=>value+1);load()},2000*(checkoutPolls+1));return()=>window.clearTimeout(timer)},[workspace?.subscription,checkoutPolls]);
  useEffect(()=>{if(!workspace)return;const billing=new URLSearchParams(window.location.search).get("billing");if(billing!=="returned")return;setNotice("Настройки оплаты обновлены. Статус подписки синхронизируется со Stripe.");window.history.replaceState({},"","/coach")},[workspace]);
  async function logout(){setLogoutBusy(true);setError("");try{await partnerPortalApi.logout()}catch(reason){setError(reason instanceof Error?reason.message:"Не удалось завершить сессию")}finally{setWorkspace(null);setLoginRequired(true);setLogoutBusy(false)}}
  if(loading)return <main className={styles.page}><div className={styles.empty}>Загружаем кабинет коуча...</div></main>;
  if(loginRequired)return <CoachLogin onDone={load}/>;
  if(!workspace)return <main className={styles.page}><div className={styles.error}>{error}</div></main>;
  const counts=workspace.counts;
  return <main className={styles.page}><div className={styles.shell}>
    <aside className={styles.sidebar}><Link className={styles.brand} href="/">ORKEN.LIFE</Link><nav>{tabs.map(([id,label,Icon])=><button key={id} className={tab===id?styles.active:""} onClick={()=>{setTab(id);setSelected(null)}}><Icon size={18}/>{label}</button>)}</nav><div className={styles.sidebarFoot}><Link className={styles.link} href="/partners"><Link2 size={15}/> Рефералы и финансы</Link><Link className={styles.link} href="/coaches">Открыть каталог</Link></div></aside>
    <section className={styles.main}><header className={styles.top}><div><span className={styles.badge}>Кабинет коуча</span><h1>{title(tab)}</h1><p>{description(tab)}</p></div><div className={styles.topActions}><span className={styles.status}>{statusLabel(workspace.profile.status)}</span><button className={styles.logoutButton} type="button" onClick={logout} disabled={logoutBusy}><LogOut size={16}/>{logoutBusy?"Выходим...":"Выйти"}</button></div></header>
    {error&&<p className={styles.error}>{error}</p>}{notice&&<p className={styles.success}>{notice}</p>}
    {workspace.profile.status!=="APPROVED"&&<div className={styles.notice}>Публичный профиль и продажи станут доступны после модерации. Рабочие инструменты и настройка уже доступны.</div>}
    {tab==="overview"&&<><CoachOnboarding workspace={workspace} openTab={setTab}/><div className={styles.metrics}><Metric label="Клиентов за счёт пакета" value={counts.coachPaidClients}/><Metric label="Самостоятельно оплачивают" value={counts.clientPaidClients}/><Metric label="Нужна внимательность" value={counts.attention}/><Metric label="Открытых заданий" value={counts.openAssignments}/></div><div className={styles.layout}><ClientsTable workspace={workspace} open={async(id)=>{setSelected(await coachApi.client(id));setTab("clients")}}/><section className={`${styles.panel} ${styles.stack}`}><h2>Быстрые действия</h2><button className={styles.button} onClick={()=>setTab(workspace.subscription?"clients":"plans")}><Plus size={17}/> {workspace.subscription?"Пригласить клиента":"Подключить пакет"}</button><button className={`${styles.button} ${styles.secondary}`} onClick={()=>setTab("scheduling")}><CalendarClock size={17}/> Настроить расписание</button><button className={`${styles.button} ${styles.secondary}`} onClick={()=>setTab("services")}><HandCoins size={17}/> Добавить услугу</button><Link className={`${styles.button} ${styles.secondary}`} href="/partners"><CircleDollarSign size={17}/> Комиссии и выплаты</Link></section></div></>}
    {tab==="clients"&&<ClientsView workspace={workspace} selected={selected} setSelected={setSelected} setError={setError} setNotice={setNotice} openPlans={()=>setTab("plans")}/>}
    {tab==="scheduling"&&<SchedulingView workspace={workspace} refresh={load} setError={setError} setNotice={setNotice}/>}
    {tab==="services"&&<ServicesView workspace={workspace} refresh={load} setError={setError} setNotice={setNotice}/>} 
    {tab==="plans"&&<PlansView workspace={workspace} refresh={load} setError={setError} setNotice={setNotice}/>}
    {tab==="site"&&<SiteView workspace={workspace} refresh={load} setError={setError} setNotice={setNotice}/>} 
    {tab==="telegram"&&<TelegramView workspace={workspace}/>}
    {tab==="rewards"&&<RewardsView workspace={workspace} refresh={load} setError={setError} setNotice={setNotice}/>} 
    {tab==="profile"&&<ProfileView workspace={workspace} refresh={load} setError={setError} setNotice={setNotice}/>} 
    </section><nav className={styles.mobileNav} aria-label="Разделы кабинета">{tabs.map(([id,label,Icon])=><button key={id} className={tab===id?styles.active:""} onClick={()=>{setTab(id);setSelected(null)}}><Icon size={19}/>{label}</button>)}</nav></div></main>
}

function CoachLogin({onDone}:{onDone:()=>void}){
  const[mode,setMode]=useState<"login"|"register">("login");
  const[email,setEmail]=useState("");const[password,setPassword]=useState("");const[passwordRepeat,setPasswordRepeat]=useState("");
  const[name,setName]=useState("");const[practice,setPractice]=useState("");const[accepted,setAccepted]=useState(false);
  const[error,setError]=useState("");const[busy,setBusy]=useState(false);const[recoveryOpen,setRecoveryOpen]=useState(false);
  async function submit(e:React.FormEvent){e.preventDefault();if(mode==="register"&&password!==passwordRepeat){setError("Пароли не совпадают");return}setBusy(true);setError("");try{if(mode==="register"){await partnerPortalApi.register({email,password,displayName:name.trim(),accountName:practice.trim()||name.trim(),accountType:"individual",idempotencyKey:makeKey()})}else{await partnerPortalApi.login({email,password})}onDone()}catch(reason){setError(reason instanceof Error?reason.message:"Не удалось продолжить")}finally{setBusy(false)}}
  const recoveryHref=`mailto:orken.eco@gmail.com?subject=${encodeURIComponent("Восстановление доступа к кабинету коуча ORKEN")}&body=${encodeURIComponent(`Email аккаунта: ${email.trim()||"укажите email"}\n\nПрошу восстановить доступ к кабинету коуча.`)}`;
  return <main className={styles.page}><section className={styles.auth} aria-labelledby="coach-auth-title"><Link className={styles.brand} href="/">ORKEN.LIFE</Link><span className={styles.badge}>Кабинет коуча</span><h1 id="coach-auth-title">{mode==="login"?"Вход для коуча":"Создайте кабинет коуча"}</h1><p>{mode==="login"?"Войдите, чтобы управлять клиентами, расписанием и пакетом мест.":"Одна регистрация открывает кабинет коуча и партнёрскую программу ORKEN."}</p><div className={styles.authTabs} role="tablist" aria-label="Вход или регистрация"><button type="button" className={mode==="login"?styles.authTabActive:""} onClick={()=>{setMode("login");setRecoveryOpen(false);setError("")}}>Войти</button><button type="button" className={mode==="register"?styles.authTabActive:""} onClick={()=>{setMode("register");setRecoveryOpen(false);setError("")}}>Зарегистрироваться</button></div><form onSubmit={submit}>{mode==="register"&&<><label>Имя и фамилия<input value={name} onChange={e=>setName(e.target.value)} autoComplete="name" minLength={2} required/></label><label>Название практики <span className={styles.optional}>необязательно</span><input value={practice} onChange={e=>setPractice(e.target.value)} autoComplete="organization" placeholder="Например, Анна Орлова"/></label></>}<label>Email<input type="email" value={email} onChange={e=>setEmail(e.target.value)} autoComplete="email" required/></label><label>Пароль<input type="password" value={password} onChange={e=>setPassword(e.target.value)} minLength={mode==="register"?12:undefined} autoComplete={mode==="register"?"new-password":"current-password"} required/>{mode==="register"&&<span className={styles.fieldHelp}>Не менее 12 символов</span>}</label>{mode==="login"&&<button className={styles.textButton} type="button" aria-expanded={recoveryOpen} onClick={()=>setRecoveryOpen(value=>!value)}><KeyRound size={15}/> Забыли пароль?</button>}{mode==="login"&&recoveryOpen&&<div className={styles.recoveryPanel}><div><h2>Восстановление доступа</h2><p>Пароль хранится в Partner Core. Отправьте запрос в поддержку с email аккаунта. Старый пароль указывать не нужно.</p></div><a className={`${styles.button} ${styles.secondary}`} href={recoveryHref}><Mail size={16}/> Написать в поддержку</a></div>}{mode==="register"&&<><label>Повторите пароль<input type="password" value={passwordRepeat} onChange={e=>setPasswordRepeat(e.target.value)} minLength={12} autoComplete="new-password" required/></label><label className={styles.consent}><input type="checkbox" checked={accepted} onChange={e=>setAccepted(e.target.checked)} required/><span>Принимаю <Link href="/offer">Оферту</Link> и <Link href="/privacy">Политику конфиденциальности</Link></span></label></>}{error&&<p className={styles.error} role="alert">{error}</p>}<button className={styles.button} disabled={busy||(mode==="register"&&!accepted)}>{mode==="register"?<UserPlus size={17}/>:<LogIn size={17}/>} {busy?"Проверяем...":mode==="register"?"Создать кабинет":"Войти"}</button></form><p className={styles.authFoot}>Учётная запись хранится в Partner Core. ORKEN не хранит пароль коуча.</p></section></main>
}

function CoachOnboarding({workspace,openTab}:{workspace:CoachWorkspaceResponse;openTab:(tab:Tab)=>void}){
  const profileReady=Boolean(workspace.profile.headline&&workspace.profile.bio&&workspace.profile.specializations.length);
  const packageReady=Boolean(workspace.subscription);
  const scheduleReady=workspace.scheduling.provider==="ORKEN"&&workspace.scheduling.active&&workspace.scheduling.availabilityRules.some(rule=>rule.active);
  const clientReady=workspace.clients.length>0;
  const steps=[
    {label:"Заполните профиль",detail:"Добавьте специализацию и информацию о себе.",done:profileReady,tab:"profile" as Tab},
    {label:"Подключите пакет",detail:packageReady?`${workspace.subscription?.plan.name}: доступно мест ${workspace.subscription?.availableSlots??"без лимита"}.`:"Стартовый пакет рассчитан на 5 клиентов.",done:packageReady,tab:"plans" as Tab},
    {label:"Настройте расписание",detail:"Укажите рабочие дни и часы внутри ORKEN.",done:scheduleReady,tab:"scheduling" as Tab},
    {label:"Пригласите клиента",detail:"Отправьте клиенту персональную ссылку подключения.",done:clientReady,tab:"clients" as Tab}
  ];
  const next=steps.find(step=>!step.done);
  return <section className={styles.onboarding}><div className={styles.onboardingHead}><div><span className={styles.badge}>Начало работы</span><h2>{next?"Подготовьте кабинет к работе":"Кабинет готов к работе"}</h2><p>{next?"Пройдите четыре шага. Настройки сохраняются, к ним можно вернуться в любое время.":"Можно приглашать клиентов, назначать шаги и давать обратную связь."}</p></div>{next&&<button className={styles.button} onClick={()=>openTab(next.tab)}>Продолжить</button>}</div><ol>{steps.map((step,index)=><li key={step.label} className={step.done?styles.onboardingDone:""}><span>{step.done?<CheckCircle2 size={19}/>:index+1}</span><button type="button" onClick={()=>openTab(step.tab)}><strong>{step.label}</strong><small>{step.detail}</small></button></li>)}</ol></section>
}
function Metric({label,value}:{label:string;value:number|string}){return <div className={styles.metric}><span>{label}</span><strong>{value}</strong></div>}
function ClientsTable({workspace,open}:{workspace:CoachWorkspaceResponse;open:(id:string)=>void}){
  return <section className={styles.panel}>
    <h2>Клиенты</h2>
    <p>Здесь собраны подопечные, их последние отметки состояния и сигналы внимания.</p>
    {workspace.clients.length>0?<div className={styles.tableWrap}><table className={styles.table}><thead><tr><th>Клиент</th><th>Среднее</th><th>Последняя отметка</th><th></th></tr></thead><tbody>{workspace.clients.slice(0,8).map(client=><tr key={client.relationshipId}><td><div className={styles.client}><span className={styles.avatar}>{client.avatarUrl?<img src={client.avatarUrl} alt=""/>:<UserRound size={17}/>}</span><div>{client.name||client.email}<br/><small className={client.attentionReason?styles.flag:styles.good}>{client.attentionReason||"Ритм стабилен"}</small></div></div></td><td>{client.weeklyAverage??"—"}</td><td>{client.lastCheckinAt?date(client.lastCheckinAt):"Нет отметок"}</td><td><button className={styles.rowButton} onClick={()=>open(client.relationshipId)}>Открыть</button></td></tr>)}</tbody></table></div>:<div className={styles.emptyGuide}>
      <UsersRound size={30}/><h3>Здесь появятся ваши клиенты</h3>
      <p>Это список подопечных, а не экран ежедневной отметки. Создайте приглашение справа. После подключения клиента вы сможете открыть его состояние, инсайты, обратную связь и задания.</p>
      <div className={styles.guideSteps}><span><strong>1</strong> Создайте ссылку</span><span><strong>2</strong> Клиент примет приглашение</span><span><strong>3</strong> Данные появятся с его согласия</span></div>
    </div>}
  </section>
}
function ClientsView({workspace,selected,setSelected,setError,setNotice,openPlans}:{workspace:CoachWorkspaceResponse;selected:CoachClientDetail|null;setSelected:(v:CoachClientDetail|null)=>void;setError:(v:string)=>void;setNotice:(v:string)=>void;openPlans:()=>void}){
  const[email,setEmail]=useState("");
  const packageSlots=workspace.subscription?.availableSlots;
  const canUsePackage=Boolean(workspace.subscription&&(packageSlots===null||packageSlots===undefined||packageSlots>0));
  const[funding,setFunding]=useState<"COACH_PAID"|"CLIENT_PAID">(canUsePackage?"COACH_PAID":"CLIENT_PAID");
  const[link,setLink]=useState("");
  const[msg,setMsg]=useState("");
  const[taskTitle,setTaskTitle]=useState("");
  const[task,setTask]=useState("");
  const[habitTitle,setHabitTitle]=useState("");
  const[habitPractice,setHabitPractice]=useState("");
  const[section,setSection]=useState<ClientSection>("state");

  useEffect(()=>setSection("state"),[selected?.client.relationshipId]);

  async function invite(){try{const result=await coachApi.invite({email:email||undefined,funding});setLink(result.connectUrl);setNotice("Приглашение создано. Отправьте ссылку клиенту — она действует 14 дней.")}catch(e){setError(e instanceof Error?e.message:"Не удалось создать приглашение")}}
  async function open(id:string){try{setSelected(await coachApi.client(id))}catch(e){setError(e instanceof Error?e.message:"Ошибка")}}
  async function sendFeedback(){if(!selected||!msg.trim())return;try{await coachApi.message(selected.client.relationshipId,msg.trim());setMsg("");setNotice("Обратная связь отправлена и уже видна клиенту в разделе «Мой коуч».");await open(selected.client.relationshipId)}catch(e){setError(e instanceof Error?e.message:"Не удалось отправить обратную связь")}}
  async function addAssignment(){if(!selected||!taskTitle.trim()||!task.trim())return;try{await coachApi.assignment(selected.client.relationshipId,{title:taskTitle.trim(),details:task.trim()});setTaskTitle("");setTask("");setNotice("Задание назначено");await open(selected.client.relationshipId)}catch(e){setError(e instanceof Error?e.message:"Не удалось назначить задание")}}
  async function addHabit(){if(!selected||!habitTitle.trim()||!habitPractice.trim())return;try{await coachApi.habit(selected.client.relationshipId,{title:habitTitle.trim(),focus:habitTitle.trim(),practice:habitPractice.trim(),why:"Поддерживает текущую цель работы с коучем"});setHabitTitle("");setHabitPractice("");setNotice("Привычка отправлена клиенту");await open(selected.client.relationshipId)}catch(e){setError(e instanceof Error?e.message:"Не удалось отправить привычку")}}

  if(!selected)return <div className={styles.layout}><ClientsTable workspace={workspace} open={open}/><section className={`${styles.panel} ${styles.form}`}><h2>Пригласить клиента</h2><p>Клиент сам подтверждает доступ к состоянию и отдельно — к дневнику.</p>{!canUsePackage&&<div className={styles.packageHint}><Package size={19}/><div><strong>{workspace.subscription?"В пакете нет свободных мест":"Пакет клиентов не подключён"}</strong><span>Приглашение всё равно можно создать: выберите оплату клиентом или подключите пакет.</span></div><button className={`${styles.button} ${styles.secondary}`} onClick={openPlans}>Выбрать пакет</button></div>}<label>Email (необязательно)<input className={styles.control} value={email} onChange={e=>setEmail(e.target.value)} /></label><label>Кто оплачивает доступ<select className={styles.select} value={funding} onChange={e=>setFunding(e.target.value as "COACH_PAID"|"CLIENT_PAID")}><option value="COACH_PAID" disabled={!canUsePackage}>Коуч, из пакета мест{!canUsePackage?" — недоступно":""}</option><option value="CLIENT_PAID">Клиент самостоятельно</option></select></label><small className={styles.fieldHelp}>{funding==="COACH_PAID"?"После принятия приглашения клиент займёт одно место в вашем пакете.":"Место в пакете не расходуется. Клиент сможет оплатить обычный тариф ORKEN самостоятельно."}</small><button className={styles.button} onClick={invite}><Plus size={17}/> Создать приглашение</button>{link&&<div className={styles.stack}><label>Ссылка для клиента<input className={styles.control} readOnly value={link}/></label><button className={`${styles.button} ${styles.secondary}`} onClick={()=>navigator.clipboard.writeText(link)}><Link2 size={16}/> Скопировать ссылку</button></div>}</section></div>;

  const clientName=selected.client.name||selected.client.email;
  const sections:Array<[ClientSection,string,typeof Activity,number?]>=[
    ["state","Состояние",Activity],
    ["insights","Инсайты",BookOpenText,selected.insights.length],
    ["feedback","Обратная связь",MessageSquare,selected.messages.filter(item=>item.authorRole==="CLIENT").length],
    ["assignments","Задания и привычки",ClipboardList,selected.assignments.filter(item=>item.status==="OPEN").length]
  ];

  return <div className={styles.stack}>
    <button className={styles.backButton} onClick={()=>setSelected(null)}><ChevronLeft size={17}/> Все клиенты</button>
    <section className={styles.clientHeader}><span className={styles.avatar}>{selected.client.avatarUrl?<img src={selected.client.avatarUrl} alt=""/>:<UserRound size={19}/>}</span><div><h2>{clientName}</h2><p>{selected.client.email} · {selected.client.status==="ACTIVE"?"Активная программа":"Доступ не активен"}</p></div><div className={styles.consentBadges}><span className={selected.client.metricsConsent?styles.goodBadge:styles.mutedBadge}>Состояние: {selected.client.metricsConsent?"доступно":"закрыто"}</span><span className={selected.client.journalConsent?styles.goodBadge:styles.mutedBadge}>Дневник: {selected.client.journalConsent?"доступен":"закрыт"}</span></div></section>
    <nav className={styles.clientNav} aria-label="Разделы карточки клиента">{sections.map(([id,label,Icon,count])=><button key={id} className={section===id?styles.activeSection:""} onClick={()=>setSection(id)}><Icon size={17}/><span>{label}</span>{count!==undefined&&count>0&&<b>{count}</b>}</button>)}</nav>

    {section==="state"&&<div className={styles.stack}>
      <div className={styles.metrics}><Metric label="Энергия" value={selected.client.latestEnergy??"—"}/><Metric label="Ясность" value={selected.client.latestClarity??"—"}/><Metric label="Устойчивость" value={selected.client.latestStability??"—"}/><Metric label="Среднее недели" value={selected.client.weeklyAverage??"—"}/></div>
      <section className={styles.panel}><div className={styles.sectionHead}><div><h2>Прогресс внутреннего состояния</h2><p>Ежедневные отметки клиента по шкале от 1 до 10.</p></div><span className={styles.badge}>{selected.metrics.length} отметок</span></div>{!selected.client.metricsConsent?<div className={styles.notice}>Клиент не дал или отозвал доступ к показателям состояния.</div>:selected.metrics.length?<StateChart points={selected.metrics}/>:<div className={styles.empty}>Клиент ещё не сделал ни одной отметки состояния.</div>}</section>
      {selected.correlations.length>0&&<section className={`${styles.panel} ${styles.stack}`}><h2>Наблюдаемые связи</h2><p>Связи рассчитаны по отметкам клиента и не означают причинность.</p>{selected.correlations.map((item,index)=><div className={styles.insightCard} key={`${item.habitTitle}-${item.metric}-${index}`}>{item.message}</div>)}</section>}
    </div>}

    {section==="insights"&&<section className={`${styles.panel} ${styles.stack}`}><div className={styles.sectionHead}><div><h2>Инсайты и записи клиента</h2><p>Записи Навигатора, которыми клиент разрешил делиться с вами.</p></div><BookOpenText size={22}/></div>{!selected.client.journalConsent?<div className={styles.notice}>Дневник закрыт. Клиент может отдельно разрешить доступ в разделе «Мой коуч».</div>:selected.insights.length?selected.insights.map(item=><article className={styles.insightCard} key={item.id}><p>{item.text}</p><small>{date(item.createdAt)}</small></article>):<div className={styles.empty}>У клиента пока нет записей и инсайтов.</div>}</section>}

    {section==="feedback"&&<div className={styles.feedbackLayout}><section className={`${styles.panel} ${styles.stack}`}><div className={styles.sectionHead}><div><h2>История обратной связи</h2><p>Ваш текст сразу появляется у клиента в разделе «Мой коуч».</p></div><MessageSquare size={22}/></div>{selected.messages.length?selected.messages.map(item=><article className={`${styles.feedbackItem} ${item.authorRole==="CLIENT"?styles.fromClient:""}`} key={item.id}><div className={styles.messageMeta}><strong>{item.authorRole==="CLIENT"?"Ответ клиента":"От вас"}</strong><small>{date(item.createdAt)}</small></div><p>{item.text}</p></article>):<div className={styles.empty}>Обратной связи пока нет. Напишите первое сообщение справа.</div>}</section><section className={`${styles.panel} ${styles.form}`}><h2>Новая обратная связь</h2><p>Сформулируйте наблюдение, рекомендацию или следующий шаг для клиента.</p><label>Текст<textarea className={styles.textarea} value={msg} onChange={e=>setMsg(e.target.value)} placeholder="Например: на этой неделе ясность стала устойчивее. Сохрани текущий ритм и обрати внимание..."/></label><button className={styles.button} disabled={selected.client.status!=="ACTIVE"||!msg.trim()} onClick={sendFeedback}><Send size={16}/> Отправить клиенту</button>{selected.client.status!=="ACTIVE"&&<div className={styles.notice}>Отправка станет доступна после активации программы.</div>}</section></div>}

    {section==="assignments"&&<div className={styles.assignmentGrid}><section className={`${styles.panel} ${styles.stack}`}><h2>Текущие задания</h2>{selected.assignments.length?selected.assignments.map(item=><article className={styles.itemCard} key={item.id}><div className={styles.itemTop}><div><span className={styles.badge}>{item.status==="OPEN"?"Открыто":"Выполнено"}</span><h3>{item.title}</h3></div>{item.status==="COMPLETED"&&<Check size={18}/>}</div><p>{item.details}</p></article>):<div className={styles.empty}>Заданий пока нет.</div>}<h2>Привычки от вас</h2>{selected.habitAssignments.length?selected.habitAssignments.map(item=><article className={styles.itemCard} key={item.id}><span className={styles.badge}>{item.status}</span><h3>{item.title}</h3><p>{item.practice}</p></article>):<div className={styles.empty}>Авторских привычек пока нет.</div>}</section><section className={`${styles.panel} ${styles.stack}`}><div className={styles.formBlock}><h2>Новое задание</h2><input className={styles.control} value={taskTitle} onChange={e=>setTaskTitle(e.target.value)} placeholder="Название задания"/><textarea className={styles.textarea} value={task} onChange={e=>setTask(e.target.value)} placeholder="Что нужно сделать"/><button className={`${styles.button} ${styles.secondary}`} disabled={selected.client.status!=="ACTIVE"||!taskTitle.trim()||!task.trim()} onClick={addAssignment}><ClipboardList size={16}/> Назначить</button></div><div className={styles.formBlock}><h2>Авторская привычка</h2><input className={styles.control} value={habitTitle} onChange={e=>setHabitTitle(e.target.value)} placeholder="Название привычки"/><textarea className={styles.textarea} value={habitPractice} onChange={e=>setHabitPractice(e.target.value)} placeholder="Практика и мягкий шаг"/><button className={`${styles.button} ${styles.secondary}`} disabled={selected.client.status!=="ACTIVE"||!habitTitle.trim()||!habitPractice.trim()} onClick={addHabit}><Plus size={16}/> Отправить привычку</button></div></section></div>}
  </div>
}
function StateChart({points}:{points:Array<{date:string;energy:number;clarity:number;stability:number}>}){
  return <div className={styles.chart}><ResponsiveContainer width="100%" height="100%"><LineChart data={points.slice(-31)} margin={{top:8,right:8,left:-18,bottom:0}}><CartesianGrid stroke="#1b2c40" vertical={false}/><XAxis dataKey="date" stroke="#7890aa" tick={{fontSize:11}} tickFormatter={(value)=>String(value).slice(5)}/><YAxis domain={[1,10]} stroke="#7890aa" tick={{fontSize:11}}/><Tooltip contentStyle={{background:"#08131f",border:"1px solid #29415b",borderRadius:6}} labelFormatter={(value)=>`Дата: ${value}`}/><Legend/><Line type="monotone" dataKey="energy" name="Энергия" stroke="#13d4ec" strokeWidth={2} dot={false}/><Line type="monotone" dataKey="clarity" name="Ясность" stroke="#a965ea" strokeWidth={2} dot={false}/><Line type="monotone" dataKey="stability" name="Устойчивость" stroke="#24d3a2" strokeWidth={2} dot={false}/></LineChart></ResponsiveContainer></div>
}
function SchedulingView({workspace,refresh,setError,setNotice}:{workspace:CoachWorkspaceResponse;refresh:()=>void;setError:(v:string)=>void;setNotice:(v:string)=>void}){
  const schedule=workspace.scheduling;
  const[timezone,setTimezone]=useState(schedule.timezone);
  const[duration,setDuration]=useState(schedule.slotDurationMinutes);
  const[bufferAfter,setBufferAfter]=useState(schedule.bufferAfterMinutes);
  const[minNotice,setMinNotice]=useState(schedule.minNoticeMinutes);
  const[horizon,setHorizon]=useState(schedule.bookingHorizonDays);
  const[active,setActive]=useState(schedule.active);
  const[rules,setRules]=useState(()=>Array.from({length:7},(_,index)=>{const found=schedule.availabilityRules.find(rule=>rule.weekday===index+1);return{weekday:index+1,active:Boolean(found?.active),startMinute:found?.startMinute??540,endMinute:found?.endMinute??1080}}));
  const[exceptionDate,setExceptionDate]=useState("");
  const[busy,setBusy]=useState(false);
  async function save(){setBusy(true);setError("");try{await coachApi.updateScheduling({provider:"ORKEN",timezone,slotDurationMinutes:duration,bufferBeforeMinutes:0,bufferAfterMinutes:bufferAfter,minNoticeMinutes:minNotice,bookingHorizonDays:horizon,active});await coachApi.updateAvailability(rules);setNotice("Расписание ORKEN сохранено");refresh()}catch(error){setError(error instanceof Error?error.message:"Не удалось сохранить расписание")}finally{setBusy(false)}}
  return <div className={styles.stack}>
    <section className={styles.scheduleIntro}><CalendarClock size={25}/><div><h2>Встроенное расписание ORKEN</h2><p>Задайте рабочие часы и исключения. Клиент выберет свободное время внутри ORKEN, без подключения внешнего календаря.</p>{schedule.provider!=="ORKEN"&&<span>После сохранения текущий внешний календарь будет заменён расписанием ORKEN.</span>}</div><Check size={20}/></section>
    <div className={styles.layout}><section className={`${styles.panel} ${styles.form}`}><h2>Рабочие часы</h2>{rules.map((rule,index)=><div className={styles.scheduleRow} key={rule.weekday}><label><input type="checkbox" checked={rule.active} onChange={event=>setRules(current=>current.map((item,i)=>i===index?{...item,active:event.target.checked}:item))}/>{weekdayLabel(rule.weekday)}</label><input className={styles.control} type="time" disabled={!rule.active} value={minuteToTime(rule.startMinute)} onChange={event=>setRules(current=>current.map((item,i)=>i===index?{...item,startMinute:timeToMinute(event.target.value)}:item))}/><span>—</span><input className={styles.control} type="time" disabled={!rule.active} value={minuteToTime(rule.endMinute)} onChange={event=>setRules(current=>current.map((item,i)=>i===index?{...item,endMinute:timeToMinute(event.target.value)}:item))}/></div>)}</section>
      <section className={`${styles.panel} ${styles.form}`}><h2>Правила записи</h2><label>Часовой пояс<input className={styles.control} value={timezone} onChange={event=>setTimezone(event.target.value)} placeholder="Europe/Moscow"/></label><div className={styles.formGrid}><label>Длительность<select className={styles.select} value={duration} onChange={event=>setDuration(Number(event.target.value))}><option value={30}>30 минут</option><option value={45}>45 минут</option><option value={60}>60 минут</option><option value={90}>90 минут</option></select></label><label>Перерыв после<input className={styles.control} type="number" min="0" max="120" value={bufferAfter} onChange={event=>setBufferAfter(Number(event.target.value))}/></label><label>Не позднее, часов<input className={styles.control} type="number" min="0" value={Math.round(minNotice/60)} onChange={event=>setMinNotice(Number(event.target.value)*60)}/></label><label>Запись вперёд, дней<input className={styles.control} type="number" min="1" max="180" value={horizon} onChange={event=>setHorizon(Number(event.target.value))}/></label></div><label><input type="checkbox" checked={active} onChange={event=>setActive(event.target.checked)}/> Принимать новые записи</label><button className={styles.button} disabled={busy} onClick={save}><Save size={17}/>{busy?"Сохраняем...":"Сохранить расписание"}</button></section></div>
    <div className={styles.layout}><section className={`${styles.panel} ${styles.form}`}><h2>Выходные и исключения</h2><div className={styles.actions}><input className={styles.control} type="date" value={exceptionDate} onChange={event=>setExceptionDate(event.target.value)}/><button className={`${styles.button} ${styles.secondary}`} disabled={!exceptionDate} onClick={async()=>{try{await coachApi.addScheduleException({date:exceptionDate,isAvailable:false,note:"Выходной"});setExceptionDate("");setNotice("Выходной добавлен");refresh()}catch(error){setError(error instanceof Error?error.message:"Ошибка")}}}>Добавить выходной</button></div>{schedule.availabilityExceptions.map(item=><div className={styles.exceptionRow} key={item.id}><span>{new Intl.DateTimeFormat("ru-RU",{dateStyle:"medium"}).format(new Date(`${item.date}T00:00:00`))}</span><small>{item.note||(!item.isAvailable?"Выходной":"Дополнительное время")}</small><button className={styles.rowButton} title="Удалить" onClick={async()=>{await coachApi.deleteScheduleException(item.id);refresh()}}><Trash2 size={16}/></button></div>)}</section>
      <section className={styles.panel}><h2>Ближайшие встречи</h2><div className={styles.stack}>{workspace.appointments.filter(item=>item.status!=="CANCELLED").slice(0,12).map(item=><article className={styles.appointment} key={item.id}><div><span className={styles.badge}>{item.status}</span><h3>{item.serviceTitle||"Консультация"}</h3><p>{new Intl.DateTimeFormat("ru-RU",{dateStyle:"medium",timeStyle:"short",timeZone:item.timezone}).format(new Date(item.startsAt))}{item.client?` · ${item.client.name||item.client.email}`:""}</p></div><div className={styles.actions}>{item.meetingUrl&&<a className={styles.rowButton} href={item.meetingUrl} target="_blank" rel="noreferrer">Встреча</a>}{item.status==="CONFIRMED"&&<button className={styles.rowButton} onClick={async()=>{await coachApi.updateAppointment(item.id,"COMPLETED");refresh()}}>Завершить</button>}</div></article>)}{workspace.appointments.length===0&&<div className={styles.empty}>Записей пока нет.</div>}</div></section></div>
  </div>
}

function ServicesView({workspace,refresh,setError,setNotice}:{workspace:CoachWorkspaceResponse;refresh:()=>void;setError:(v:string)=>void;setNotice:(v:string)=>void}){
  const offers=workspace.serviceOffers;
  const paidServicesEnabled=workspace.commerce?.servicesEnabled??false;
  const[type,setType]=useState<"ONGOING_SUPPORT"|"CONSULTATION">("ONGOING_SUPPORT");
  const[model,setModel]=useState<"INCLUDED"|"CLIENT_PAID">(paidServicesEnabled?"CLIENT_PAID":"INCLUDED");
  const[title,setTitle]=useState("");const[description,setDescription]=useState("");const[amount,setAmount]=useState("0");
  async function save(){try{await coachApi.saveOffer({type,paymentModel:model,title,description,amount:model==="CLIENT_PAID"?Math.round(Number(amount)*100):0,currency:"usd",calendlyEventTypeUri:null,calendlySchedulingUrl:null});setNotice(model==="CLIENT_PAID"?"Черновик сохранён. Администратор настроит доли оплаты перед публикацией.":"Услуга сохранена. Отправьте её на модерацию.");refresh()}catch(e){setError(e instanceof Error?e.message:"Ошибка")}}
  return <div className={styles.layout}><section className={styles.panel}><h2>Ваши услуги</h2><p>Опишите форматы работы, которые увидит клиент в каталоге после модерации.</p><div className={styles.stack}>{offers.map(o=><article className={styles.card} key={o.id}><span className={styles.badge}>{o.status}</span><h3>{o.title}</h3><p>{o.description}</p><strong>{o.paymentModel==="INCLUDED"?"Включено в программу":money(o.amount,o.currency)}</strong>{o.paymentModel==="CLIENT_PAID"&&o.coachShareBps==null&&<p className={styles.flag}>Доли оплаты ещё не настроены администратором</p>}<button className={`${styles.button} ${styles.secondary}`} disabled={o.status!=="DRAFT"||(o.paymentModel==="CLIENT_PAID"&&o.coachShareBps==null)} onClick={async()=>{try{await coachApi.submitOffer(o.id);setNotice("Услуга отправлена на модерацию");refresh()}catch(e){setError(e instanceof Error?e.message:"Ошибка")}}}>Отправить на модерацию</button></article>)}{offers.length===0&&<div className={styles.empty}>Услуги пока не добавлены.</div>}</div></section><section className={`${styles.panel} ${styles.form}`}><h2>Новая услуга</h2>{!paidServicesEnabled&&<div className={styles.notice}>Сейчас можно добавить услугу, включённую в вашу программу. Продажа отдельных консультаций через ORKEN появится после настройки выплат.</div>}<label>Формат<select className={styles.select} value={type} onChange={e=>setType(e.target.value as "ONGOING_SUPPORT"|"CONSULTATION")}><option value="ONGOING_SUPPORT">Ежемесячное ведение</option><option value="CONSULTATION">Разовая консультация</option></select></label><label>Оплата<select className={styles.select} value={model} onChange={e=>setModel(e.target.value as "INCLUDED"|"CLIENT_PAID")}><option value="INCLUDED">Включено в программу коуча</option>{paidServicesEnabled&&<option value="CLIENT_PAID">Клиент платит через ORKEN</option>}</select></label><input className={styles.control} value={title} onChange={e=>setTitle(e.target.value)} placeholder="Название"/><textarea className={styles.textarea} value={description} onChange={e=>setDescription(e.target.value)} placeholder="Что получает клиент"/>{model==="CLIENT_PAID"&&<label>Цена, $<input className={styles.control} type="number" min="0" step="0.01" value={amount} onChange={e=>setAmount(e.target.value)}/></label>}{type==="CONSULTATION"&&<p className={styles.fieldHelp}>Клиент выберет свободное время во встроенном расписании ORKEN.</p>}<button className={styles.button} disabled={!title.trim()||!description.trim()||(model==="CLIENT_PAID"&&Number(amount)<=0)} onClick={save}>Сохранить черновик</button></section></div>
}
function PlansView({workspace,refresh,setError,setNotice}:{workspace:CoachWorkspaceResponse;refresh:()=>void;setError:(v:string)=>void;setNotice:(v:string)=>void}){
  const[busyPlan,setBusyPlan]=useState<string|null>(null);const[billingBusy,setBillingBusy]=useState(false);
  const packagesEnabled=workspace.commerce?.packagesEnabled??false;
  const currentPlanId=workspace.subscription?.plan.id;
  async function checkout(planId:string){setBusyPlan(planId);setError("");try{const result=await coachApi.checkoutPlan(planId,makeKey());if(!result.url)throw new Error("Платёжная страница не создана. Попробуйте ещё раз или обратитесь в поддержку.");window.location.assign(result.url)}catch(error){setError(error instanceof Error?error.message:"Не удалось открыть оплату пакета");setBusyPlan(null)}}
  async function openBilling(){setBillingBusy(true);setError("");try{const result=await coachApi.subscriptionPortal();window.location.assign(result.url)}catch(error){setError(error instanceof Error?error.message:"Не удалось открыть управление оплатой");setBillingBusy(false)}}
  async function changePlan(planId:string,planName:string){if(!window.confirm(`Перейти на пакет «${planName}»? Новый лимит начнёт действовать сразу, новая цена — со следующего списания.`))return;setBusyPlan(planId);setError("");try{const result=await coachApi.changePlan(planId,makeKey());const next=result.nextChargeAt?` Следующее списание: ${date(result.nextChargeAt)}.`:"";setNotice(`Пакет изменён. Новый лимит уже доступен.${next}`);refresh()}catch(error){setError(error instanceof Error?error.message:"Не удалось изменить пакет")}finally{setBusyPlan(null)}}
  return <div className={styles.stack}>
    {workspace.subscription?<section className={styles.panel}><div className={styles.sectionHead}><div><h2>Текущий пакет: {workspace.subscription.plan.name}</h2><p>{workspace.subscription.coachPaidClients} из {workspace.subscription.clientLimit} мест занято. Клиенты со своей подпиской: {workspace.subscription.clientPaidClients}.</p><p className={styles.fieldHelp}>{workspace.subscription.cancelAtPeriodEnd?`Подписка завершится ${workspace.subscription.currentPeriodEnd?date(workspace.subscription.currentPeriodEnd):"в конце оплаченного периода"}.`:`Следующее списание: ${workspace.subscription.currentPeriodEnd?date(workspace.subscription.currentPeriodEnd):"дата уточняется"}.`}</p></div><span className={styles.goodBadge}>{workspace.subscription.status}</span></div><div className={styles.billingActions}><button className={`${styles.button} ${styles.secondary}`} type="button" onClick={openBilling} disabled={billingBusy}><CreditCard size={17}/>{billingBusy?"Открываем Stripe...":"Карта, счета и отмена"}</button><span>Платёжные данные открываются на защищённой странице Stripe.</span></div></section>:<section className={styles.planIntro}><Package size={24}/><div><h2>Выберите пакет клиентов</h2><p>Пакет нужен только для клиентов, доступ которым оплачиваете вы. Приглашать клиентов с самостоятельной оплатой можно без пакета.</p></div></section>}
    {!packagesEnabled&&<div className={styles.notice}>Онлайн-оплата пакетов сейчас отключена администратором. Тарифы можно посмотреть, но подключить их до включения оплаты нельзя.</div>}
    <div className={styles.cards}>{workspace.plans.map(plan=>{
      const current=plan.id===currentPlanId;
      const busy=busyPlan===plan.id;
      return <article className={`${styles.card} ${current?styles.currentPlan:""}`} key={plan.id}><span className={styles.badge}>{plan.includedClients?`${plan.includedClients} мест`:"Индивидуально"}</span><h3>{plan.name}</h3><p>{plan.description}</p><strong>{plan.customQuote?"По запросу":`${money(plan.amount,plan.currency)} / месяц`}</strong>{plan.customQuote?<a className={`${styles.button} ${styles.secondary}`} href="mailto:orken.eco@gmail.com?subject=Пакет ORKEN более 30 клиентов">Запросить условия</a>:current?<button className={styles.button} disabled>Текущий пакет</button>:workspace.subscription?<button className={`${styles.button} ${styles.secondary}`} disabled={!packagesEnabled||Boolean(busyPlan)} onClick={()=>changePlan(plan.id,plan.name)}>{busy?"Меняем пакет...":"Перейти на пакет"}</button>:<button className={styles.button} disabled={!packagesEnabled||Boolean(busyPlan)} onClick={()=>checkout(plan.id)}>{busy?"Открываем оплату...":"Подключить пакет"}</button>}</article>
    })}</div>
  </div>
}
function SiteView({workspace,refresh,setError,setNotice}:{workspace:CoachWorkspaceResponse;refresh:()=>void;setError:(v:string)=>void;setNotice:(v:string)=>void}){const[slug,setSlug]=useState(workspace.profile.slug);return <div className={styles.stack}>{workspace.sites.map(site=><SiteEditor key={site.id} site={site} refresh={refresh} setError={setError} setNotice={setNotice}/>)}<section className={styles.panel}><h2>Подключить сайт</h2><label>Адрес на ORKEN<input className={styles.control} value={slug} onChange={e=>setSlug(e.target.value.toLowerCase().replace(/[^a-z0-9-]/g,"-"))}/></label><div className={styles.cards}>{workspace.sitePlans.map(plan=><article className={styles.card} key={plan.id}><h3>{plan.name}</h3><p>{plan.code==="premium"?"Свой домен, редактируемые блоки, календарь и AI-чат.":"Готовый шаблон на поддомене ORKEN."}</p><strong>{money(plan.setupAmount,plan.currency)} + {money(plan.monthlySupportAmount,plan.currency)}/мес</strong><button className={styles.button} onClick={async()=>{try{const r=await coachApi.checkoutSite(plan.id,slug);if(r.url)location.assign(r.url)}catch(e){setError(e instanceof Error?e.message:"Ошибка")}}}>Подключить</button></article>)}</div></section></div>}
function SiteEditor({site,refresh,setError,setNotice}:{site:CoachWorkspaceResponse["sites"][number];refresh:()=>void;setError:(v:string)=>void;setNotice:(v:string)=>void}){const content=site.content||{};const[heading,setHeading]=useState(String(content.title||""));const[subtitle,setSubtitle]=useState(String(content.subtitle||""));const[domain,setDomain]=useState(site.customDomain||"");const[verification,setVerification]=useState<{record:string;type:string;value:string}|null>(null);return <section className={`${styles.panel} ${styles.form}`}><div className={styles.siteHead}><div><h2>Ваш сайт</h2><p><span className={styles.badge}>{site.status}</span> <a className={styles.link} href={`https://${site.customDomain||`${site.slug}.orken.life`}`} target="_blank">{site.customDomain||`${site.slug}.orken.life`} <ExternalLink size={14}/></a></p></div></div>{site.planCode==="premium"&&<><label>Заголовок<input className={styles.control} value={heading} onChange={e=>setHeading(e.target.value)}/></label><label>Короткое описание<textarea className={styles.textarea} value={subtitle} onChange={e=>setSubtitle(e.target.value)}/></label><label>Собственный домен<input className={styles.control} value={domain} onChange={e=>setDomain(e.target.value)} placeholder="coach.example.com"/></label><div className={styles.actions}><button className={styles.button} onClick={async()=>{try{const result=await coachApi.updateSite(site.id,{content:{...content,title:heading,subtitle},customDomain:domain||null});setVerification(result.verification||null);setNotice("Настройки сайта сохранены");refresh()}catch(e){setError(e instanceof Error?e.message:"Ошибка")}}}>Сохранить</button>{site.customDomainStatus==="PENDING_VERIFICATION"&&<button className={`${styles.button} ${styles.secondary}`} onClick={async()=>{try{await coachApi.verifySiteDomain(site.id);setNotice("Домен подтверждён");refresh()}catch(e){setError(e instanceof Error?e.message:"TXT-запись пока не найдена")}}}>Проверить домен</button>}</div>{verification&&<div className={styles.notice}>Добавьте DNS-запись: <code>{verification.type} {verification.record} = {verification.value}</code></div>}</>}</section>}
function TelegramView({workspace}:{workspace:CoachWorkspaceResponse}){return <section className={`${styles.panel} ${styles.telegramPanel}`}><MessageSquare size={28}/><div><h2>Telegram-бот ORKEN</h2><p>Отправьте ссылку клиенту, чтобы он мог перейти в ORKEN из Telegram. Бот использует ваш публичный профиль и сохраняет связь с клиентом.</p>{workspace.integrations.telegramBotUsername?<div className={styles.actions}><a className={styles.button} href={`https://t.me/${workspace.integrations.telegramBotUsername}?start=coach_${workspace.profile.slug}`} target="_blank" rel="noreferrer">Открыть бота</a><button className={`${styles.button} ${styles.secondary}`} onClick={()=>navigator.clipboard.writeText(`https://t.me/${workspace.integrations.telegramBotUsername}?start=coach_${workspace.profile.slug}`)}>Скопировать ссылку</button></div>:<span className={styles.flag}>Telegram-бот временно недоступен</span>}</div></section>}
function RewardsView({workspace,refresh,setError,setNotice}:{workspace:CoachWorkspaceResponse;refresh:()=>void;setError:(v:string)=>void;setNotice:(v:string)=>void}){const[title,setTitle]=useState("");const[description,setDescription]=useState("");const[points,setPoints]=useState("500");return <div className={styles.layout}><section className={styles.panel}><h2>Награды за ORKEN Points</h2>{workspace.rewards.map(r=><article className={styles.card} key={r.id}><span className={styles.badge}>{r.status}</span><h3>{r.title}</h3><p>{r.description}</p><strong>{r.pointsCost} Points</strong></article>)}</section><section className={`${styles.panel} ${styles.form}`}><h2>Новая награда</h2><p>Награда появится у клиентов после модерации.</p><input className={styles.control} value={title} onChange={e=>setTitle(e.target.value)} placeholder="Название"/><textarea className={styles.textarea} value={description} onChange={e=>setDescription(e.target.value)} placeholder="Что получает клиент"/><input className={styles.control} type="number" value={points} onChange={e=>setPoints(e.target.value)}/><button className={styles.button} onClick={async()=>{try{await coachApi.createReward({title,description,pointsCost:Number(points),entitlementType:"manual"});setNotice("Награда отправлена на модерацию");refresh()}catch(e){setError(e instanceof Error?e.message:"Ошибка")}}}>Отправить</button></section></div>}
function ProfileView({workspace,refresh,setError,setNotice}:{workspace:CoachWorkspaceResponse;refresh:()=>void;setError:(v:string)=>void;setNotice:(v:string)=>void}){const p=workspace.profile;const[name,setName]=useState(p.displayName);const[slug,setSlug]=useState(p.slug);const[headline,setHeadline]=useState(p.headline||"");const[bio,setBio]=useState(p.bio||"");const[city,setCity]=useState(p.city||"");const[spec,setSpec]=useState(p.specializations.join(", "));const[avatar,setAvatar]=useState(p.avatarUrl||"");const[accepting,setAccepting]=useState(p.acceptingOrders);return <section className={`${styles.panel} ${styles.form}`}><h2>Публичный профиль</h2><div className={styles.photoUpload}>{avatar?<img src={avatar} alt="Фото профиля"/>:<UserRound/>}<label className={styles.button}><ImageUp size={17}/> Загрузить фото<input type="file" accept="image/jpeg,image/png,image/webp" onChange={async e=>{const file=e.target.files?.[0];if(!file)return;try{const result=await coachApi.uploadAvatar(file);setAvatar(result.avatarUrl);setNotice("Фото загружено и отправлено на модерацию");refresh()}catch(reason){setError(reason instanceof Error?reason.message:"Не удалось загрузить фото")}}}/></label></div><div className={styles.formGrid}><label>Имя<input className={styles.control} value={name} onChange={e=>setName(e.target.value)}/></label><label>Адрес профиля<input className={styles.control} value={slug} onChange={e=>setSlug(e.target.value)}/></label><label>Город<input className={styles.control} value={city} onChange={e=>setCity(e.target.value)}/></label></div><label>Короткое описание<input className={styles.control} value={headline} onChange={e=>setHeadline(e.target.value)}/></label><label>О себе<textarea className={styles.textarea} value={bio} onChange={e=>setBio(e.target.value)}/></label><label>Специализации через запятую<input className={styles.control} value={spec} onChange={e=>setSpec(e.target.value)}/></label><label><input type="checkbox" checked={accepting} onChange={e=>setAccepting(e.target.checked)}/> Принимаю новые заказы</label><button className={styles.button} onClick={async()=>{try{await coachApi.profile({displayName:name,slug,headline,bio,city,specializations:spec.split(",").map(x=>x.trim()).filter(Boolean),languages:p.languages,avatarUrl:avatar||null,acceptingOrders:accepting});setNotice("Профиль сохранён и отправлен на повторную модерацию");refresh()}catch(e){setError(e instanceof Error?e.message:"Ошибка")}}}>Сохранить</button></section>}
function title(tab:Tab){return ({overview:"Рабочий обзор",clients:"Клиенты",scheduling:"Расписание",services:"Услуги и тарифы",plans:"Пакет клиентов",site:"Сайт коуча",telegram:"Telegram",rewards:"Награды",profile:"Профиль"} as const)[tab]}
function description(tab:Tab){return ({overview:"Состояние практики и клиенты, которым сейчас нужна поддержка.",clients:"Динамика, дневник, задания и обратная связь.",scheduling:"Свободное время и предстоящие встречи внутри ORKEN.",services:"Форматы ведения и консультаций для ваших клиентов.",plans:"Места для клиентов, доступ которым оплачивает коуч.",site:"Поддомен ORKEN или собственный домен.",telegram:"Переход клиента в ORKEN через общего бота.",rewards:"Модерируемые бонусы за внутреннюю валюту.",profile:"Данные, которые видит пользователь в каталоге."} as const)[tab]}
function statusLabel(status:string){return ({APPROVED:"Профиль одобрен",PENDING_REVIEW:"На модерации",REJECTED:"Нужны исправления",SUSPENDED:"Доступ приостановлен",DRAFT:"Черновик"} as Record<string,string>)[status]||status}
function weekdayLabel(value:number){return ["","Понедельник","Вторник","Среда","Четверг","Пятница","Суббота","Воскресенье"][value]}
function minuteToTime(value:number){return `${String(Math.floor(value/60)).padStart(2,"0")}:${String(value%60).padStart(2,"0")}`}
function timeToMinute(value:string){const[hours,minutes]=value.split(":").map(Number);return hours*60+minutes}
function date(v:string){return new Intl.DateTimeFormat("ru-RU",{dateStyle:"medium"}).format(new Date(v))}function money(a:number,c:string){return new Intl.NumberFormat("ru-RU",{style:"currency",currency:c.toUpperCase(),maximumFractionDigits:0}).format(a/100)}
